<div class="tariff-editor"><p>مبالغ به ریال؛ نرخ ۱۰۰ برابر یک درصد است.</p><div class="form-grid grid grid-cols-1 gap-5 md:grid-cols-2">@foreach(['base_fee'=>'مبلغ پایه','minimum_fee'=>'حداقل دستمزد','maximum_fee'=>'سقف دستمزد'] as $k=>$text)<label>{{ $text }}<input type="number" min="0" x-model.number="values.rules.{{ $k }}"></label>@endforeach</div><h3>پله‌های محاسبه</h3><template x-for="(tier,index) in values.rules.tiers" :key="index"><div class="tier-row"><label>سقف ارزش؛ خالی یعنی نامحدود<input type="number" x-model="tier.up_to"></label><label>نرخ<input type="number" step="0.001" x-model.number="tier.rate_bps"></label><button type="button" @click="values.rules.tiers.splice(index,1)" :disabled="values.rules.tiers.length===1">حذف</button></div></template><button type="button" @click="values.rules.tiers.push({up_to:null,rate_bps:0})">افزودن پله</button><div class="form-grid grid grid-cols-1 gap-5 md:grid-cols-2">@foreach(range(1,5) as $n)<label>ضریب هیئت {{ $n }} نفره<input type="number" x-model.number="values.rules.panel_multipliers['{{ $n }}']" min="10000" max="50000"></label>@endforeach</div></div>